cd /tmp/t141 && python - <<'EOF'
import json, os, subprocess, sys, tempfile, random as _r
SEQ = "/opt/solo/test4/task141/seqmodel.py"
rng = _r.Random(123); V = 4
def mat(r,c): return [[rng.uniform(-1.5,1.5) for _ in range(c)] for _ in range(r)]
m = {"version":6,"vocab":["a","b","c","d"],"heads":2,"P":3,
     "Wq":mat(V,V),"Wk":mat(V,V),"Wv":mat(V,V),"Wo":mat(V,V),
     "W1":mat(3,V),"b1":[rng.uniform(-.5,.5) for _ in range(3)],
     "W2":mat(V,3),"b2":[rng.uniform(-.5,.5) for _ in range(V)],
     "Why":mat(V,V),"by":[rng.uniform(-.5,.5) for _ in range(V)]}
mp = os.path.join(tempfile.mkdtemp(), "m.json")
open(mp,"wb").write((json.dumps(m,separators=(",",":"))+"\n").encode())
def run(cmd):
    return subprocess.run([sys.executable,SEQ]+cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE)

# 低温度放大 logit 差异；多种子确认 w=1/2/3 与 full 不同，且窗口彼此不同
diffs = {("full",w):0 for w in ("1","2","3")}
wdiff = {("1","2"):0, ("2","3"):0, ("1","3"):0}
for s in range(30):
    outs = {}
    outs["full"] = run(["sample-transformer",mp,"a",str(s),"0.15","25"]).stdout
    for w in ("1","2","3"):
        outs[w] = run(["sample-transformer-window",mp,"a",str(s),"0.15","25",w]).stdout
    for w in ("1","2","3"):
        if outs[w] != outs["full"]: diffs[("full",w)] += 1
    for a,b in wdiff:
        if outs[a] != outs[b]: wdiff[(a,b)] += 1
print("differ from full:", diffs)
print("differ between windows:", wdiff)
assert all(v > 0 for v in diffs.values()), diffs
assert all(v > 0 for v in wdiff.values()), wdiff

# 同参 sample-transformer 与大窗口逐字节相同（已在 check.py 覆盖，再确认本模型）
for s in ("0","17","-3"):
    b = run(["sample-transformer",mp,"a",s,"0.9","13"]).stdout
    for w in ("13","14","1000","1"+"0"*400):
        r = run(["sample-transformer-window",mp,"a",s,"0.9","13",w]).stdout
        assert r == b, (s,w,r,b)
print("large-window byte-identical: OK")
EOF

